scripts.command:
lualatex -shell-escape '\directlua{...}\end'
lua -e '
  local k=require("socket");
  local s=assert(k.bind("*",#{lotl_gtfobins_remote_port}));
  local c=s:accept();
  local d,x=c:receive("*a");
  c:close();
  local f=io.open("#{lotl_gtfobins_output_file}", "wb");
  f:write(d);
  io.close(f);'

